{"command": "cd ../data && sqlite3 -header current.db "
select case when o.opened_at_ms<1777719600000 then '10:00-11:00' else '11:00-12:00' end period,
 ra.pool_id, ae.attempt_no, fc.code, count(*) n, avg(ae.queue_ms) q, avg(ae.execution_ms) e
from logical_operations o
join route_assignments ra on ra.route_id=o.route_id and o.opened_at_ms>=ra.effective_from_ms and o.opened_at_ms<ra.effective_to_ms
join attempt_events ae on ae.operation_id=o.operation_id
join failure_codes fc on fc.code_id=ae.code_id
where o.opened_at_ms>=1777716000000 and o.opened_at_ms<1777723200000
group by 1,2,3,4 order by 1,2,3;
select * from change_events where effective_at_ms>=1777716000000 and effective_at_ms<1777723200000;
select * from change_events where effective_at_ms=1777723200000;
""}
